const requestDataExport = `-- name: RequestDataExport :exec
WITH pending AS (
  SELECT 1
  FROM data_exports
  WHERE user_id = $1
    AND ready_at IS NULL
),
gone AS (
  DELETE FROM data_exports
  WHERE user_id = $1
    AND NOT EXISTS (
      SELECT 1
      FROM pending
    )
)
INSERT INTO data_exports (user_id, lang)
SELECT $1,
  $2
WHERE NOT EXISTS (
    SELECT 1
    FROM pending
  )
`

type RequestDataExportParams struct {
	UserID pgtype.UUID `json:"user_id"`
	Lang   string      `json:"lang"`
}

// queues an export unless the user has one pending, then their older ones are deleted
// (the trigger queues their objects for the purge)
func (q *Queries) RequestDataExport(ctx context.Context, arg RequestDataExportParams) error {
	_, err := q.db.Exec(ctx, requestDataExport, arg.UserID, arg.Lang)
	return err
}

